function burst(x,y,color,n=9){for(let i=0;i<n;i++)particles.push({x,y,vx:(rand()-.5)*180,vy:(rand()-.5)*180,life:.45+rand()*.45,color})}
function update(dt){if(state!=='play')return;elapsed+=dt;distance+=dt*13;ui.distance.textContent=Math.floor(distance);fire.cool=Math.max(0,fire.cool-dt);let steer=(keys.arrowleft||keys.a||keys.left?-1:0)+(keys.arrowright||keys.d||keys.right?1:0);boatX+=steer*dt*.48;boatX=Math.max(.24,Math.min(.76,boatX));spawn-=dt;if(spawn<=0){addObject();spawn=Math.max(.34,1.08-elapsed*.007)+rand()*.45}
for(let i=objects.length-1;i>=0;i--){let o=objects[i];o.y+=o.speed*dt*(1+elapsed*.002);o.x+=Math.sin(elapsed*1.5+o.phase)*dt*13;if(o.type==='fish'&&o.y>H*.5)o.x+=(boatX*W-o.x)*dt*.12;if(o.type==='fish')for(let j=shots.length-1;j>=0;j--){let s=shots[j];if(Math.abs(s.x-o.x)<27*(o.scale+.5)&&Math.abs(s.y-o.y)<23*(o.scale+.5)){shots.splice(j,1);objects.splice(i,1);score+=10;ui.score.textContent=score;burst(o.x,o.y,'#e7aa65',14);o.hit=true;break}}if(o.hit)continue;let dx=o.x-boatX*W,dy=o.y-H*.78,collision=Math.abs(dx)<(o.type==='log'?48:39)&&Math.abs(dy)<(o.type==='log'?28:31);if(collision){if(o.type==='supply'){score+=25;ui.score.textContent=score;burst(o.x,o.y,'#f1d082',12)}else if(o.type==='fish'||o.type==='log'){lives--;updateHealth();shake=13;flash=.2;burst(o.x,o.y,o.type==='fish'?'#d4754d':'#98744d',15);if(lives<=0){objects.splice(i,1);end(false);return}}objects.splice(i,1);continue}if(o.y>H+60)objects.splice(i,1)}
for(let i=shots.length-1;i>=0;i--){shots[i].y-=shots[i].v*dt;if(shots[i].y<-30)shots.splice(i,1)}for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.98;p.vy*=.98;p.life-=dt;if(p.life<=0)particles.splice(i,1)}shake=Math.max(0,shake-dt*28);flash=Math.max(0,flash-dt);if(distance>=1170)end(true)}
function draw(){ctx.save();if(shake)ctx.translate((rand()-.5)*shake,(rand()-.5)*shake);drawBackground(0);for(const o of objects){if(o.type==='fish')drawFish(o);else if(o.type==='log')drawLog(o);else drawSupply(o)}for(const s of shots){ctx.strokeStyle='#e7d59d';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(s.x,s.y+10);ctx.lineTo(s.x,s.y-13);ctx.stroke();ctx.fillStyle='#fff0c4';ctx.beginPath();ctx.moveTo(s.x,s.y-18);ctx.lineTo(s.x-4,s.y-10);ctx.lineTo(s.x+4,s.y-10);ctx.fill()}for(const p of particles){ctx.globalAlpha=Math.max(0,p.life);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,2.4,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;if(state!=='title'||true)drawBoat();if(flash){ctx.fillStyle=`rgba(228,87,54,${flash*.6})`;ctx.fillRect(0,0,W,H)}ctx.restore()}
function frame(t){let dt=Math.min(.04,(t-last)/1000||0);last=t;update(dt);draw();requestAnimationFrame(frame)}requestAnimationFrame(frame);
})();
</script>
</body>
</html>

